-- Создание таблицы shops для хранения информации о магазинах

CREATE TABLE IF NOT EXISTS `shops` (
    `id` INT(11) NOT NULL AUTO_INCREMENT,
    `name` VARCHAR(255) NOT NULL COMMENT 'Название магазина',
    `address` VARCHAR(500) NOT NULL COMMENT 'Адрес магазина',
    `latitude` DECIMAL(10, 8) NOT NULL COMMENT 'Широта (координата Y)',
    `longitude` DECIMAL(11, 8) NOT NULL COMMENT 'Долгота (координата X)',
    `description` TEXT COMMENT 'Описание магазина',
    `how_to_get` TEXT COMMENT 'Как добраться до магазина',
    `phone` VARCHAR(20) COMMENT 'Телефон магазина',
    `work_hours` VARCHAR(100) COMMENT 'Режим работы',
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    KEY `idx_coordinates` (`latitude`, `longitude`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Магазины';

-- Добавление 5 примерных магазинов в Москве
INSERT INTO `shops` (`name`, `address`, `latitude`, `longitude`, `description`, `how_to_get`, `phone`, `work_hours`) VALUES
('Косметика на Красной площади', 'ул. Никольская, д. 15, ТЦ "Никольская площадь", 2 этаж', 55.7558, 37.6173, 'Флагманский магазин в самом центре Москвы. Здесь вы найдете широкий ассортимент премиальной косметики и парфюмерии.', 'Добраться можно на метро: станции "Охотный ряд", "Площадь Революции" или "Лубянка". Выйти к Красной площади и пройти по Никольской улице 200 метров. Магазин находится в торговом центре "Никольская площадь" на втором этаже.', '+7 (495) 123-45-67', 'Ежедневно с 10:00 до 22:00'),
('Косметика в ТЦ Авиапарк', 'Ходынский бульвар, д. 4, ТЦ "Авиапарк", 1 этаж, секция 120', 55.7887, 37.5342, 'Современный магазин в крупнейшем торговом центре Москвы. Огромный выбор косметики от ведущих мировых брендов.', 'Добраться можно на метро: станция "Октябрьское Поле" (5 минут пешком) или "Полежаевская" (10 минут пешком). Также можно доехать на автобусе № 26, 39, 155, 597 до остановки "Ходынский бульвар". Торговый центр "Авиапарк" находится рядом с метро.', '+7 (495) 234-56-78', 'Ежедневно с 10:00 до 23:00'),
('Косметика в ТЦ Европейский', 'пл. Киевского Вокзала, д. 2, ТЦ "Европейский", 3 этаж, бутик 308', 55.7447, 37.5665, 'Элегантный бутик косметики в премиальном торговом центре. У нас представлены эксклюзивные коллекции и профессиональные консультанты.', 'Добраться можно на метро: станция "Киевская" (кольцевая, Арбатско-Покровская или Филевская линии). Выйти к Киевскому вокзалу. ТЦ "Европейский" расположен прямо над станцией метро. Наш бутик находится на третьем этаже.', '+7 (495) 345-67-89', 'Ежедневно с 10:00 до 22:00'),
('Косметика в ТЦ Мега Химки', 'МКАД, 71-й километр, ТЦ "Мега Химки", 1 этаж, вход 3', 55.8944, 37.4511, 'Крупный магазин косметики в популярном торговом центре. Здесь вы найдете выгодные предложения и акции на все категории товаров.', 'Добраться можно на автомобиле по МКАД, съезд на 71-м километре. Или на общественном транспорте: автобус № 400, 400э от станции метро "Речной вокзал" до остановки "Мега Химки". Также ходит бесплатный автобус от метро "Ховрино" каждые 15 минут.', '+7 (495) 456-78-90', 'Ежедневно с 10:00 до 23:00'),
('Косметика на Савеловской', 'ул. Сущевский Вал, д. 9, стр. 1, 1 этаж', 55.7939, 37.5895, 'Уютный магазин в самом центре города. Мы специализируемся на натуральной и органической косметике, а также предоставляем персональные консультации.', 'Добраться можно на метро: станция "Савеловская" (Серпуховско-Тимирязевская линия). Выйти к Сущевскому Валу, пройти 300 метров по направлению к центру. Магазин находится на первом этаже жилого дома, вход с улицы. Также можно доехать на трамвае № 19, 27 до остановки "Сущевский Вал".', '+7 (495) 567-89-01', 'Пн-Пт: 10:00-21:00, Сб-Вс: 11:00-20:00');

